import {namibiaTime,residentActivity} from './namibia-time.js?v=life17';
import * as T from './three.module.js';import {loadFarmer} from './farmer-rig.js?v=life17';import {createAgent,updateAgent} from './resident-ai.js?v=neighbours16';import {createFarmPet} from './farm-pets.js?v=neighbours16';import {rectBlocked} from './farm-layouts.js?v=neighbours16';
export function createFarmResidents({parent,p,plan,register,load=true}){const residents=[],pets=[],pending=[];let timeClock=1,local=namibiaTime();const blocked=(x,z)=>rectBlocked(plan.blocks,x,z,.08)||(plan.fields&&Math.abs(x-plan.fields.x)<plan.fields.w/2+.5&&Math.abs(z-plan.fields.z)<plan.fields.d/2+.5);
 for(const [i,person]of plan.people.entries()){const root=new T.Group();root.name=person.name+' · '+person.role;root.position.set(p.x+5+i*2,.2,p.z+18);parent.add(root);const agent=createAgent(p.id+'-'+person.name,root.position.x,root.position.z,plan.zones.yard,{person:true,radius:person.role==='child'?.3:.42,speed:person.role==='child'?1.4:1}),record={...person,root,agent,rig:null};residents.push(record);}
 function loadModels(names=null){for(const [i,record]of residents.entries()){const person=record;if(record.loading||record.rig||(names&&!names.includes(record.name)))continue;record.loading=true;pending.push(loadFarmer(person.variant).then(rig=>{record.rig=rig;rig.root.scale.set(person.height*person.width,person.height,person.height*.96);record.root.add(rig.root);rig.model.traverse(o=>{if(o.isMesh){o.castShadow=false;const mats=Array.isArray(o.material)?o.material:[o.material];if(/torso|shirt|jacket/i.test(o.name))for(const m of mats)m.color.set(['#91a2a2','#b39b8f','#b9b087','#879eab'][(i+p.id.length)%4]);}});rig.update(0,0);rig.mixer.setTime(record.agent.phase);register(record.root,{kind:'resident',farmId:p.id,residentName:person.name,role:person.role,x:record.agent.x,z:record.agent.z,approach:{x:record.agent.x,z:record.agent.z+1.5}});}).catch(e=>{record.error=e.message;console.warn('Resident unavailable:',person.name,e.message);}));}return Promise.allSettled(pending);}
 if(load)loadModels();
 for(const [i,type]of ['dog','cat'].entries()){const model=createFarmPet(type,p.id.length+i),agent=createAgent(p.id+'-'+type,p.x+6+i*3,p.z+12,plan.zones.yard,{radius:type==='cat'?.28:.5,speed:type==='cat'?.85:1.5});parent.add(model.root);pets.push({type,model,agent});register(model.root,{kind:'resident',farmId:p.id,residentName:type==='dog'?'Buddy':'Miso',role:type,x:agent.x,z:agent.z,approach:{x:agent.x,z:agent.z+1}});}
 return {residents,pets,loadModels,get ready(){return Promise.allSettled(pending);},update(dt,extra=[]){timeClock+=dt;if(timeClock>1){local=namibiaTime();timeClock=0;}const peers=[...residents,...pets].map(r=>r.agent).concat(extra);for(const r of residents){if(r.travel)continue;r.activity=residentActivity(r.role,p.id+'-'+r.name,local);r.isOutside=!['sleep','school'].includes(r.activity);r.root.visible=r.isOutside;if(!r.isOutside){if(r.ball)r.ball.visible=false;continue;}const playing=r.activity==='play';r.agent.speed=playing?1.65:r.role==='child'?1.15:1;const motion=updateAgent(r.agent,dt,blocked,peers);r.root.position.set(r.agent.x,.2+(playing&&r.agent.mode==='look'?Math.abs(Math.sin(r.agent.phase*5))*.13:0),r.agent.z);r.root.rotation.y=r.agent.heading;const task=r.agent.mode==='work'&&r.role!=='child'?'plant':null;r.rig?.update(dt,motion.moved/dt,task);if(r.role==='child'){if(!r.ball){r.ball=new T.Mesh(new T.SphereGeometry(.16,10,8),new T.MeshStandardMaterial({color:'#e0ba7a',roughness:.8}));parent.add(r.ball);}r.ball.visible=playing;const x=r.agent.x+Math.sin(r.agent.heading)*.8,z=r.agent.z+Math.cos(r.agent.heading)*.8;r.ball.position.set(blocked(x,z)?r.agent.x:x,.38+Math.abs(Math.sin(r.agent.phase*4))*.12,blocked(x,z)?r.agent.z:z);r.ball.rotation.x+=motion.moved*4;}}for(const pet of pets){const motion=updateAgent(pet.agent,dt,blocked,peers);pet.model.root.position.set(pet.agent.x,.2,pet.agent.z);pet.model.root.rotation.y=pet.agent.heading;pet.model.update(dt,pet.agent,motion.moved);}}};
}
